"use client";

import { Search } from "lucide-react";
import { useState } from "react";

import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";

export function StudentsFilter() {
  const [search, setSearch] = useState("");
  const [tier, setTier] = useState("all");
  const [status, setStatus] = useState("all");

  function updateSearch(value: string) {
    setSearch(value);
    console.log("search", value);
  }

  function updateTier(value: string) {
    setTier(value);
    console.log("tier", value);
  }

  function updateStatus(value: string) {
    setStatus(value);
    console.log("status", value);
  }

  function clearFilters() {
    setSearch("");
    setTier("all");
    setStatus("all");
  }

  return (
    <div className="mt-6 flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
      <div className="flex flex-1 flex-col gap-3 sm:flex-row sm:items-center">
        <div className="relative w-full sm:w-72">
          <Search
            size={17}
            className="absolute left-3 top-1/2 -translate-y-1/2 text-muted"
          />
          <Input
            value={search}
            onChange={(event) => updateSearch(event.target.value)}
            placeholder="Search by name, email, or roll…"
            className="h-10 pl-9"
            aria-label="Search students"
          />
        </div>
        <Select
          value={tier}
          onChange={(event) => updateTier(event.target.value)}
          className="h-10 w-full sm:w-44"
          aria-label="Filter by tier"
        >
          <option value="all">All tiers</option>
          <option value="university">University</option>
          <option value="other">Other</option>
        </Select>
        <Select
          value={status}
          onChange={(event) => updateStatus(event.target.value)}
          className="h-10 w-full sm:w-44"
          aria-label="Filter by status"
        >
          <option value="all">All status</option>
          <option value="verified">Verified</option>
          <option value="unverified">Unverified</option>
          <option value="pending">Pending approval</option>
        </Select>
      </div>
      <button
        type="button"
        onClick={clearFilters}
        className="min-h-11 text-left text-sm text-muted hover:text-foreground lg:min-h-0 lg:text-right"
      >
        Clear filters
      </button>
      <p className="sr-only">NOTE: wire to URL query params in a later pass.</p>
    </div>
  );
}
